package com.farmdirect.controller;
import com.farmdirect.dao.OrderDAO;import com.farmdirect.model.User;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet("/checkout") public class CheckoutServlet extends HttpServlet{
 @SuppressWarnings("unchecked") protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");if(u==null||!"CUSTOMER".equals(u.getRole())){p.sendRedirect("login.jsp");return;}try{new OrderDAO().place(u.getId(),(Map<Integer,Integer>)q.getSession().getAttribute("cart"));q.getSession().removeAttribute("cart");p.sendRedirect("orders");}catch(Exception e){q.getSession().setAttribute("message",e.getMessage());p.sendRedirect("cart");}}
}